public class Main {
    static long maxMod(long[] arr, long m) {
        int n = arr.length;
        int mid = n / 2;

        long[] left = Arrays.copyOfRange(arr, 0, mid);
        long[] right = Arrays.copyOfRange(arr, mid, n);

        List<Long> leftSums = new ArrayList<>();
        List<Long> rightSums = new ArrayList<>();

        int leftSize = left.length;
        int rightSize = right.length;

        // Generate all subset sums for left half
        int totalLeft = 1 << leftSize;
        for (int mask = 0; mask < totalLeft; mask++) {
            long sum = 0;
            for (int i = 0; i < leftSize; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += left[i];
                }
            }
            leftSums.add(sum % m);
        }

        // Generate all subset sums for right half
        int totalRight = 1 << rightSize;
        for (int mask = 0; mask < totalRight; mask++) {
            long sum = 0;
            for (int i = 0; i < rightSize; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += right[i];
                }
            }
            rightSums.add(sum % m);
        }

        Collections.sort(rightSums);

        long best = 0;

        for (long x : leftSums) {
            long target = (m - 1 - x + m) % m;
            int idx = upperBound(rightSums, target);
            if (idx >= 0) {
                long y = rightSums.get(idx);
                best = Math.max(best, (x + y) % m);
            }
        }

        return best;
    }

    static int upperBound(List<Long> list, long target) {
        int l = 0, r = list.size() - 1, ans = -1;
        while (l <= r) {
            int mid = (l + r) >>> 1;
            if (list.get(mid) <= target) {
                ans = mid;
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
        return ans;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        long m = fs.nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextLong();
        }
        System.out.println(maxMod(a, m));
    }

    // FastScanner for input
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
